    elif month in [4, 6, 9, 11]:
        if day < 1 or day > 30:
            return False
    else:  # February
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            if day < 1 or day > 29:
                return False
        else:
            if day < 1 or day > 28:
                return False

